[
  {
    "severity": "P1明显",
    "category": "ua-default-style",
    "description": "输入框占位符（业务账号、业务账号密码）及点击区域未见自定义焦点态逻辑，在移动端 WebView 中极易触发浏览器默认的蓝色聚焦环（Outline）或系统原生光标颜色，干扰“酱园琥珀”色调。",
    "suggestion": "显式设置 input:focus { outline: none; }，并定义 caret-color 为琥珀色（#E68E4F），确保交互色彩统一。"
  },
  {
    "severity": "P1明显",
    "category": "contrast",
    "description": "表单标签“账号”、“密码”以及底部说明文字与深色背景对比度过低，尤其在室外强光或低亮度模式下难以阅读。",
    "suggestion": "提升非关键文字的明度，建议将文本颜色从深灰色调整为暖纸色的低饱和度版本（如浅棕灰），以达到 WCAG AA 级标准。"
  },
  {
    "severity": "P1明显",
    "category": "dark-mode-flaw",
    "description": "暗色模式下卡片（Card）背景色与页面背景色值过于接近，层级区分主要依赖细边框，导致容器感破碎，不符合“圆角卡片”设计原则。",
    "suggestion": "微调卡片背景色明度（比背景略亮），或通过琥珀色微弱阴影（Restrained Shadow）模拟光感，增强悬浮层级。"
  },
  {
    "severity": "P2瑕疵",
    "category": "spacing",
    "description": "账号输入项与密码标签之间的纵向间距过紧，与卡片上下内边距的疏朗感不匹配，导致信息组块划分不清晰。",
    "suggestion": "增大两组输入框之间的间距（Margin-Bottom），使其大于标签与输入框之间的内部间距，遵循亲密性原则。"
  },
  {
    "severity": "P2瑕疵",
    "category": "typography",
    "description": "顶部印章图标内的子标题“B-1005”字号极小且笔画纤细，在 375px 分辨率下存在明显的识别障碍。",
    "suggestion": "适当增加该处字号并改用中粗体，确保在移动端高像素密度屏下的可读性。"
  },
  {
    "severity": "P2瑕疵",
    "category": "inconsistency",
    "description": "“登录”按钮使用了较重的外发光/发光阴影，虽然符合琥珀主题，但与设计规范中“克制阴影”的要求略有冲突，显得略微“工业电子感”。",
    "suggestion": "收敛按钮阴影的扩散半径，改用内发光或更细腻的渐变来表现琥珀质感，减少发光造成的视觉干扰。"
  },
  {
    "severity": "P2瑕疵",
    "category": "typography",
    "description": "底部辅助文字“企业账号登录 · ...”字号疑似低于 12px，且字间距过挤，在暗色背景下易产生视觉糊团。",
    "suggestion": "建议字号不低于 12px，并适当增加字间距（letter-spacing: 0.5px），提升底部信息的精致感。"
  }
]
